import type { CarId } from '../vehicles/CarSpecs'

/**
 * Per-car runtime rig table for the real-model GLBs (spec §5, Task 4 output).
 * GENERATED by scripts/emit-rigs.mjs from rigs/reports/<id>.report.json —
 * never hand-edit: rerun `npm run optimize-cars && npm run emit-rigs`.
 * tests/carassets.test.ts regenerates this file in CI and fails on any diff,
 * and re-hashes every public/models GLB against its report's glbSha256.
 */
export interface CarRig {
/** [fl, fr, rl, rr] metres — per-corner visual/spin radius (tyres may differ per corner) */
  wheelRadius: [number, number, number, number]
/** [fl, fr, rl, rr] hub centres in MODEL space (nose convention: −z forward,
 *  world −x = the car's left); [x, hubY, z] — hubY is the measured hub height
 *  the physics rides on, NOT radius − sink (tread-dominant corners differ 20-40 mm) */
  wheelPos: [[number, number, number], [number, number, number], [number, number, number], [number, number, number]]
/** body min-Y when parked on the wheels (m); negative = splitter dips below road */
  groundClearance: number
/** true → no paint-* materials in the GLB, garage swatches keep author colours */
  bakedPaint: boolean
/** add emissive glow planes over baked lamp textures */
  lampGlow: boolean
/** world z of the head-/brake-light glow planes (percentile body face, pushed outboard) */
  lampZ: [front: number, rear: number]
/** rear badge decal position (tail side, +z; measured tail face + 20 mm, y off the shell) */
  logoAnchor: [number, number, number]
/** nitro flame origins, [left, right], measured AT the tail face (no runtime nudge) */
  nitroAnchor: [[number, number, number], [number, number, number]]
}

